import{_ as r,C as t,o as s,c as i,E as a,a2 as l}from"./chunks/framework.IIAdu7fg.js";const d="/joinwell52/assets/execution-boundaries-20261028/stopped-but-tool-ran.figure.en.svg",w=JSON.parse('{"title":"The AI stopped. Why did a queued tool still start?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The AI stopped. Why did a queued tool still start?","date":"2026-10-28","published_date":"2026-10-28","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"The AI stopped. Why did a queued tool still start?","summary":"Reporting a failure does not necessarily stop execution. We ran the same 16 controlled schedules against OpenAI Agents Python before and after its fix.","cover":"/assets/execution-boundaries-20261028/stopped-but-tool-ran.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Pinned source; local before-and-after replay of upstream regression tests","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-10-28-stopped-but-tool-ran.md","filePath":"en/research/2026-10-28-stopped-but-tool-ran.md","lastUpdated":null}'),c={name:"en/research/2026-10-28-stopped-but-tool-ran.md"};function h(p,e,u,g,m,f){const o=t("ArticleCover"),n=t("ArticleTableScroll");return s(),i("div",null,[a(o,{image:"/assets/execution-boundaries-20261028/stopped-but-tool-ran.cover-v1.png",kicker:"Open-source engineering · Controlled comparison",title:"The AI stopped. Why did a queued tool still start?",summary:"Reporting a failure does not necessarily stop execution. We ran the same 16 controlled schedules against OpenAI Agents Python before and after its fix.",version:"2026-10-28",languageHref:"/zh/research/2026-10-28-stopped-but-tool-ran",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=l('<h1 id="the-ai-stopped-why-did-a-queued-tool-still-start" tabindex="-1">The AI stopped. Why did a queued tool still start? <a class="header-anchor" href="#the-ai-stopped-why-did-a-queued-tool-still-start" aria-label="Permalink to &quot;The AI stopped. Why did a queued tool still start?&quot;">​</a></h1><p>Imagine asking an AI assistant to inspect some material, organize files, and then take an action. A check fails during the first step. The assistant reports that the task has failed and execution has stopped.</p><p>That sounds reassuring. But a second tool may already be running, while a third is waiting in a queue. <strong>Reporting a failure</strong> and <strong>preventing the next action</strong> are different events. For an agent that can call external tools, the time between them matters more than the final message.</p><h2 id="why-we-followed-this-change" tabindex="-1">Why we followed this change <a class="header-anchor" href="#why-we-followed-this-change" aria-label="Permalink to &quot;Why we followed this change&quot;">​</a></h2><p>Among the <a href="https://joinwell52-ai.github.io/joinwell52/en/runtime/daily-intelligence/2026-10-28" target="_blank" rel="noreferrer">18 engineering developments we collected on October 28</a>, <a href="https://github.com/openai/openai-agents-python/pull/5446" target="_blank" rel="noreferrer">OpenAI Agents Python PR #5446</a> describes a precise gap. A function-tool failure had already been selected as the run&#39;s error. While previously completed output was being finalized, a queued native tool could still proceed. A parallel input guardrail rejection created a related stopping boundary.</p><p>Our question was: <strong>When does “stop” actually reach the execution queue?</strong> Pinned code on both sides of the fix and a common test make that question testable.</p><h2 id="separating-reported-error-from-stopped-action" tabindex="-1">Separating “reported error” from “stopped action” <a class="header-anchor" href="#separating-reported-error-from-stopped-action" aria-label="Permalink to &quot;Separating “reported error” from “stopped action”&quot;">​</a></h2><p>We did not call a real model or let tools change real files or network resources. The upstream regression test uses a <code>ScriptedModel</code> to emit a known sequence of tool calls. Synthetic custom and local shell tools record whether they start and receive cancellation. The test controls the moment when one tool is active, another is queued, and a function failure is selected.</p><p>We ran the same test against the pre-fix commit <a href="https://github.com/openai/openai-agents-python/tree/a91f0bfe013a63ce0ad8935c8c2d25047d249002" target="_blank" rel="noreferrer"><code>a91f0bfe</code></a> and merge commit <a href="https://github.com/openai/openai-agents-python/tree/cd26bbbc52847845fde73b9952b51e62e2bcbdc0" target="_blank" rel="noreferrer"><code>cd26bbbc</code></a>. It combines two tool kinds, streaming or non-streaming, rejected or accepted input, and cleanup with or without an error: 16 controlled schedules.</p><table tabindex="0"><thead><tr><th>Source</th><th>Result across 16 schedules</th><th>What the result means</th></tr></thead><tbody><tr><td>Before the fix</td><td><strong>16/16 failed</strong></td><td>The active native tool did not receive the expected cancellation during this window.</td></tr><tr><td>Merge commit</td><td><strong>16/16 passed</strong></td><td>In the same schedules, the active tool was cancelled and the queued call stayed behind the stopping boundary.</td></tr></tbody></table><p>We also ran both related test files at the merge commit: <strong>84/84 passed</strong>. This does not mean 84 real-world situations are safe; it means those regression checks passed. All 16 pre-fix failures reached the same cancellation assertion. We printed the module path to verify that the old-source run actually loaded the old source.</p><p><img src="'+d+'" alt="A selected function failure cancels an active tool and keeps a queued call behind the boundary"></p><p><em>Figure: the controlled schedule we tested. It does not imply rollback of a tool action already completed elsewhere.</em></p><h2 id="what-changed-and-what-did-not" tabindex="-1">What changed, and what did not <a class="header-anchor" href="#what-changed-and-what-did-not" aria-label="Permalink to &quot;What changed, and what did not&quot;">​</a></h2><p>The fix makes a selected failure visible to other tool execution: active native tools receive cancellation, and their queue stops releasing new calls. It still gives already completed output a bounded finalization window. A cancellation requested by the caller takes priority.</p><p>This suggests three different promises: <strong>stop new work, cancel active work, and undo an external side effect</strong>. Our controlled test supports the first two within its specified schedules. It cannot show that a remote service reverses an action already submitted. We did not check which packaged release includes the merged PR.</p><p>If an agent handles real work for you, a concrete question is: after a failed check or a stop request, can it tell you which calls never started, which had already started, and which may still have an uncertain external outcome?</p><p>For engineers, the next question is how a run record should represent the interval between external submission and cancellation, so a resumed agent knows which effects need human verification. For users, have you seen a task shown as stopped while a file or remote state still changed? The sequence of events is more informative than the label “stopped.”</p><p>See the <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-10-28-execution-boundaries/00-report.md" target="_blank" rel="noreferrer">public experiment report</a> for pinned versions, commands, and limits. This was a <strong>local replay of an upstream regression test against old and fixed source</strong>, not a production incident reproduction. <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',19))])}const y=r(c,[["render",h]]);export{w as __pageData,y as default};
